import{_ as s,r as e,o as d,c as l,e as a,a as r,s as i}from"./chunks/framework.CXcwiNg-.js";const k=JSON.parse('{"title":"Data Table Field - October CMS - 3.x","titleTemplate":false,"description":"Form Widget","frontmatter":{"subtitle":"Form Widget","shortname":"Data Table"},"headers":[{"level":4,"title":"Column Configuration","slug":"column-configuration","link":"#column-configuration","children":[]},{"level":4,"title":"Column Validation","slug":"column-validation","link":"#column-validation","children":[]},{"level":4,"title":"AJAX Handlers","slug":"ajax-handlers","link":"#ajax-handlers","children":[]}],"relativePath":"3.x/element/form/widget-datatable.md","filePath":"3.x/element/form/widget-datatable.md"}'),c={name:"3.x/element/form/widget-datatable.md"};function p(u,t,h,g,m,f){const n=e("pre-heading"),o=e("post-heading");return d(),l("div",null,[a(n),t[0]||(t[0]=r("h1",null,"Data Table Field",-1)),a(o),t[1]||(t[1]=i(`<p><code>datatable</code> - renders an editable table of records, formatted as a grid. Cell content can be editable directly in the grid, allowing for the management of several rows and columns of information.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">data</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> datatable
    <span class="token key atrule">adding</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
    <span class="token key atrule">deleting</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
    <span class="token key atrule">columns</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>
    <span class="token key atrule">recordsPerPage</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
    <span class="token key atrule">searching</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><div class="custom-block tip"><p>In order to use this with a model, the field should be defined in the <a href="./../../extend/system/models.html">jsonable property</a> or anything that can handle storing as an array.</p></div><p>The following <a href="./../form-fields.html">field properties</a> are supported and commonly used.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>a name when displaying the form field to the user.</td></tr><tr><td><strong>default</strong></td><td>specifies a default string value, optional.</td></tr><tr><td><strong>comment</strong></td><td>places a descriptive comment below the field.</td></tr><tr><td><strong>adding</strong></td><td>allow records to be added to the data table. Default: <code>true</code>.</td></tr><tr><td><strong>btnAddRowLabel</strong></td><td>defines a custom label for the &quot;Add Row Above&quot; button.</td></tr><tr><td><strong>btnAddRowBelowLabel</strong></td><td>defines a custom label for the &quot;Add Row Below&quot; button.</td></tr><tr><td><strong>btnDeleteRowLabel</strong></td><td>defines a custom label for the &quot;Delete Row&quot; button.</td></tr><tr><td><strong>columns</strong></td><td>an array representing the column configuration of the data table. See the <em>Column configuration</em> section below.</td></tr><tr><td><strong>deleting</strong></td><td>allow records to be deleted from the data table. Default: <code>true</code>.</td></tr><tr><td><strong>dynamicHeight</strong></td><td>if <code>true</code>, the data table&#39;s height will extend or shrink depending on the records added, up to the maximum size defined by the <code>height</code> configuration value. Default: <code>false</code>.</td></tr><tr><td><strong>fieldName</strong></td><td>defines a custom field name to use in the POST data sent from the data table. Leave blank to use the default field alias.</td></tr><tr><td><strong>height</strong></td><td>the data table&#39;s height, in pixels. If set to <code>false</code>, the data table will stretch to fit the field container.</td></tr><tr><td><strong>keyFrom</strong></td><td>the data attribute to use for keying each record. This should usually be set to <code>id</code>. Only supports integer values.</td></tr><tr><td><strong>postbackHandlerName</strong></td><td>specifies the AJAX handler name in which the data table content will be sent with. When set to <code>null</code> (default), the handler name will be auto-detected from the request name used by the form which contains the data table. It is recommended to keep this as <code>null</code>.</td></tr><tr><td><strong>recordsPerPage</strong></td><td>the number of records to show per page. If set to <code>false</code>, the pagination will be disabled.</td></tr><tr><td><strong>searching</strong></td><td>allow records to be searched via a search box. Default: <code>false</code>.</td></tr><tr><td><strong>toolbar</strong></td><td>an array representing the toolbar configuration of the data table.</td></tr></tbody></table></div><h4 id="column-configuration"><a href="#column-configuration" class="header-anchor">#</a> Column Configuration</h4><p>The data table widget allows for the specification of columns as an array via the <code>columns</code> configuration variable. Each column should use the field name as a key, and the following configuration variables to set up the field.</p><p>Example:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">columns</span><span class="token punctuation">:</span>
    <span class="token key atrule">id</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> string
        <span class="token key atrule">title</span><span class="token punctuation">:</span> ID
        <span class="token key atrule">validation</span><span class="token punctuation">:</span>
            <span class="token key atrule">integer</span><span class="token punctuation">:</span>
                <span class="token key atrule">message</span><span class="token punctuation">:</span> Please enter a number
    <span class="token key atrule">name</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> string
        <span class="token key atrule">title</span><span class="token punctuation">:</span> Name
</code></pre></div><div class="table"><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>type</strong></td><td>the input type for this column&#39;s cells. Must be one of the following: <code>string</code>, <code>checkbox</code>, <code>dropdown</code> or <code>autocomplete</code>.</td></tr><tr><td><strong>options</strong></td><td>used only for <code>dropdown</code> and <code>autocomplete</code> columns. The array key defines the option value, and the array value defines the option label. See the AJAX Handlers section below.</td></tr><tr><td><strong>readOnly</strong></td><td>whether this column is read-only. Default: <code>false</code>.</td></tr><tr><td><strong>title</strong></td><td>defines the column&#39;s title.</td></tr><tr><td><strong>validation</strong></td><td>an array specifying the validation for the content of the column&#39;s cells. See the <em>Column validation</em> section below.</td></tr><tr><td><strong>width</strong></td><td>defines the width of the column, in pixels.</td></tr></tbody></table></div><h4 id="column-validation"><a href="#column-validation" class="header-anchor">#</a> Column Validation</h4><p>Column cells can be validated against the below types of validation. Validation should be specified as an array, with the type of validation used as a key, and an optional message specified as the <code>message</code> attrbute for that validation.</p><div class="table"><table tabindex="0"><thead><tr><th>Validation</th><th>Description</th></tr></thead><tbody><tr><td><strong>float</strong></td><td>Validates the data as a float. An optional boolean <code>allowNegative</code> attribute can be provided, allowing for negative float numbers.</td></tr><tr><td><strong>integer</strong></td><td>Validates the data as an integer. An optional boolean <code>allowNegative</code> attribute can be provided, allowing for negative integers.</td></tr><tr><td><strong>length</strong></td><td>Validates the data to be of a certain length. An integer <code>min</code> and <code>max</code> attribute must be provided, representing the minimum and maximum number of characters that must be entered.</td></tr><tr><td><strong>regex</strong></td><td>Validates the data against a regular expression. A string <code>pattern</code> attribute must be provided, defining the regular expression to test the data against.</td></tr><tr><td><strong>required</strong></td><td>Validates that the data must be entered before saving.</td></tr></tbody></table></div><h4 id="ajax-handlers"><a href="#ajax-handlers" class="header-anchor">#</a> AJAX Handlers</h4><p>For columns of type <code>dropdown</code> or <code>autocomplete</code>, the list of available options can be provided through an AJAX handler defined in the model.</p><p>The handler must follow the naming convention <code>getFieldNameDataTableOptions()</code>, where <code>FieldName</code> matches the name of the field defined in the form configuration.</p><p>The method should return an associative array, where the array key is used as the stored value and the array value is used as the display label in the data table.</p><p>For example, with a field named <strong>country</strong> the <code>getCountryDataTableOptions</code> is used.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getCountryDataTableOptions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Country</span><span class="token operator">::</span><span class="token function">pluck</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;code&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>This will automatically populate the options for the <code>country</code> field in the DataTable.</p>`,20))])}const y=s(c,[["render",p]]);export{k as __pageData,y as default};
